public static int nullSafeHashCode(long[] array) {
	int hash = 0;
	if (array == null) {
		return hash;
	}
	for (long num : array) {
		hash = 37 * hash + Long.hashCode(num);
	}
	return hash;
}

public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hashCode = 17;
    for (int i = 0; i < array.length; i++) {
        hashCode = 31 * hashCode + (int) (array[i] ^ (array[i] >>> 32));
    }
    return hashCode;
}

