public String format(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    // Initialize the string buffer
    StringBuffer sbuf = new StringBuffer();

    // Get the conversion pattern
    PatternLayout patternLayout = (PatternLayout) this.getLayout();
    String pattern = patternLayout.getConversionPattern();

    // Parse the conversion pattern and format the log event
    int start = 0;
    int end = pattern.length();
    while (start < end) {
        int percentIndex = pattern.indexOf('%', start);
        int curlyBraceIndex = pattern.indexOf('{', start);
        if (percentIndex == -1 && curlyBraceIndex == -1) {
            // No more conversion specifiers or patterns found
            break;
        }

        if (percentIndex != -1 && (curlyBraceIndex == -1 || percentIndex < curlyBraceIndex)) {
            // Handle conversion specifier
            int formatSpecifierIndex = percentIndex + 1;
            String conversionCharacter = pattern.substring(formatSpecifierIndex, formatSpecifierIndex + 1);
            switch (conversionCharacter) {
                // Handle the conversion specifiers
                case "c": // Class name
                    sbuf.append(event.getLoggerName());
                    break;
                case "d": // Date
                    String dateFormat = pattern.substring(formatSpecifierIndex + 1, pattern.indexOf('}', formatSpecifierIndex + 1));
                    sbuf.append(event.getTimeStamp());
                    break;
                case "F": // File name
                    sbuf.append(event.getLocationInformation().getFilename());
                    break;
                case "l": // Line number
                    sbuf.append(event.getLocationInformation().getLineNumber());
                    break;
                case "m": // Message
                    sbuf.append(event.getMessage());
                    break;
                case "M": // Method name
                    sbuf.append(event.getLocationInformation().getMethodName());
                    break;
                case "n": // Logger name
                    sbuf.append(event.getLoggerName());
                    break;
                case "p": // Level
                    sbuf.append(event.getLevel());
                    break;
                case "t": // Thread name
                    sbuf.append(event.getThreadName());
                    break;
                default:
                    throw new IllegalArgumentException("Unknown conversion specifier '" + conversionCharacter + "'");
            }
            start = percentIndex + 2;
        } else if (curlyBraceIndex != -1) {
            // Handle pattern
            String patternString = pattern.substring(curlyBraceIndex + 1, pattern.indexOf('}', curlyBraceIndex + 1));
            int patternStart = curlyBraceIndex + 1;
            int patternEnd = pattern.indexOf('}', curlyBraceIndex + 1);
            String patternResult = this.parsePatternString(patternString, event, patternStart, patternEnd);
            sbuf.append(patternResult);
            start = patternEnd + 1;
        }
    }

    // Return the formatted string
    return sbuf.toString();
}

