    int numVertices = resultMap.size();
    int numEdges = 0;
    for (V vertex : resultMap.values()) {
        target.addVertex(vertex);
        for (int i = 0; i < numVertices; i++) {
            if (i % 2 == 0) {
                target.addEdge(vertex, resultMap.get(i));
            } else {
                target.addEdge(resultMap.get(i), vertex);
            }
            numEdges++;
        }
    }
}

