public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.getSerializedSize(message);
    int size = messageSize + CodedOutputStream.computeRawVarint32Size(messageSize);
    if (size > buffer.capacity()) {
        buffer = LinkedBuffer.allocate(size);
    }
    CodedOutputStream cos = CodedOutputStream.newInstance(buffer);
    cos.writeRawVarint32(messageSize);
    schema.writeTo(message, cos);
    cos.flush();
    out.write(buffer.array(), 0, size);
    return size;
}

@Override
public int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message, buffer);
    int headerSize = decodeVarint32(size, false);
    int sizeWithHeader = size + headerSize;
    if (out.writableBytes() < sizeWithHeader) {
        throw new IllegalStateException("The output stream does not have enough capacity for the message");
    }
    int bytesWritten = 0;
    bytesWritten += encodeVarint32(size, out);
    bytesWritten += schema.writeTo(message, out, buffer);
    return bytesWritten;
}

