public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    timeRanges.add(new TimeRange(Math.max(0, start), Math.min(end, FETCH_DATA_DURATION)));
    int i = 1;
    while (i * FETCH_DATA_DURATION <= end) {
        long newStart = Math.min(i * FETCH_DATA_DURATION, end);
        long newEnd = Math.min((i + 1) * FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(newStart, newEnd));
        i++;
    }
    return timeRanges;
}

