public void removeFromTreeEdgeList() {
    // Check if the current edge has a previous and next edge
    if (previous != null && next != null) {
        // Update the previous edge to point to the next edge
        previous.next = next;
        // Update the next edge to point to the previous edge
        next.previous = previous;
    } else if (previous == null && next != null) {
        // If there is no previous edge, but a next edge, set the head of the list to the next edge
        head = next;
        // Update the next edge to point to the previous edge (null)
        next.previous = null;
    } else if (previous != null && next == null) {
        // If there is no next edge, but a previous edge, set the tail of the list to the previous edge
        tail = previous;
        // Update the previous edge to point to the next edge (null)
        previous.next = null;
    } else {
        // If there are no edges in the list, set the head and tail to null
        head = null;
        tail = null;
    }
}

