public String function(Reader arg0) throws IOException {
    /*
     * Read characters from the stream until we reach the end of the string (represented by a null byte)
     * and return the resulting string.
     */
    StringBuilder builder = new StringBuilder();
    boolean endOfStream = false;
    while (!endOfStream) {
        // Read the next byte from the stream
        int nextByte = arg0.read();
        if (nextByte == -1) {
            endOfStream = true;
        } else if (nextByte == 0) {
            // If we encounter a null byte, then we have reached the end of the string
            endOfStream = true;
        } else {
            // If we encounter a non-null byte, then we need to append it to our string
            builder.append((char) nextByte);
        }
    }
    return builder.toString();
}

