public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    // find the escape characters
    Pattern escapePattern = Pattern.compile("\\\\.");
    Matcher matcher = escapePattern.matcher(str);
    StringBuilder sb = new StringBuilder();
    while (matcher.find()) {
        // grab the matched pattern
        String escape = matcher.group();
        if (escape.length() > 1) {
            // if it's a valid escape character pattern, unescape it
            sb.append(unescape(escape));
        } else {
            // otherwise append the original character
            sb.append(escape);
        }
    }
    return sb.toString();
}

private static String unescape(String escape) {
    switch (escape) {
        case "\\b":
            return "\b";
        case "\\t":
            return "\t";
        case "\\n":
            return "\n";
        case "\\f":
            return "\f";
        case "\\r":
            return "\r";
        case "\\'":
        case "\\\"":
            return escape;
        default:
            throw new IllegalArgumentException("Invalid escape sequence: " + escape);
    }
}

String unescapeJava(String str) {
	if (str == null) {
		return null;
	}
	StringBuilder output = new StringBuilder();
	for (int i = 0; i < str.length(); i++) {
		char ch = str.charAt(i);
		if (ch == '\\') {
			if (i + 2 >= str.length()) {
				output.append('\\');
			} else {
				char nextChar = str.charAt(i + 1);
				switch (nextChar) {
				case 'n':
					output.append('\n');
					i += 2;
					break;
				case 'r':
					output.append('\r');
					i += 2;
					break;
				case 't':
					output.append('\t');
					i += 2;
					break;
				case 'b':
					output.append('\b');
					i += 2;
					break;
				case 'f':
					output.append('\f');
					i += 2;
					break;
				case '\\':
					output.append('\\');
					i += 2;
					break;
				default:
					output.append('\\');
					output.append(nextChar);
					i += 2;
					break;
				}
			}
		} else {
			output.append(ch);
		}
	}
	return output.toString();
}

