private static String javaCharset(String charset) {
        // Step 1: Check if charset is valid and convert to lowercase
        if (charset == null) {
            throw new IllegalArgumentException("charset must not be null");
        }
        String charsetLower = charset.toLowerCase();

        // Step 2: Map MIME charset to Java charset
        String javaCharset;
        switch (charsetLower) {
            case "us-ascii":
                javaCharset = "US-ASCII";
                break;
            case "utf-8":
                javaCharset = "UTF-8";
                break;
            case "utf-16":
                javaCharset = "UTF-16";
                break;
            case "utf-16le":
                javaCharset = "UTF-16LE";
                break;
            case "utf-16be":
                javaCharset = "UTF-16BE";
                break;
            case "iso-8859-1":
                javaCharset = "ISO-8859-1";
                break;
            default:
                javaCharset = "Unknown";
        }

        // Step 3: Return Java charset
        return javaCharset;
    }

