    if (charset.equalsIgnoreCase("US-ASCII")) {
        return "ISO-8859-1";
    } else if (charset.equalsIgnoreCase("ISO-8859-1")) {
        return "UTF-8";
    } else if (charset.equalsIgnoreCase("ISO-8859-2")) {
        return "ISO-8859-1";
