private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Creating a new circulator to traverse the component boundary in the given direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Looping through the nodes on the component boundary until the predicate is satisfied or the stop node is reached
    while (circ.hasNext() && circ.peek() != stop && !predicate.test(circ.peek())) {
        circ.next();
    }

    // If the predicate is satisfied, return a circulator to the node satisfying the predicate
    if (predicate.test(circ.peek())) {
        return circ;
    }

    // If the stop node is reached, return a circulator to the stop node
    else {
        return new OuterFaceCirculator(stop, dir);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Circulator current = OuterFaceCirculator.of(start);
    while (current.node != stop && !predicate.test(current.node)) {
        current = current.next(dir);
    }
    return current;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
  OuterFaceCirculator circulator = new OuterFaceCirculator(start,dir);
  while(circulator.getNode() != stop){
    Node currentNode = circulator.getNode();
    if(predicate.test(currentNode)){
      return circulator;
    }
    circulator.moveToNext();
  }
  return circulator;
}

public OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    /*
     * Step 1: Validate the input
     */
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }
    if (dir != FORWARD && dir != BACKWARD) {
        throw new IllegalArgumentException("Invalid direction: " + dir);
    }

    /*
     * Step 2: Initialize the circulator to the start node
     */
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    /*
     * Step 3: Iterate over the nodes on the outer face
     *         until we find a node that satisfies the predicate
     *         or reach the stop node
     */
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
        if (node == stop) {
            break;
        }
    }

    /*
     * Step 4: If no node was found that satisfies the predicate,
     *         return a circulator to the stop node
     */
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result;
    if (predicate.test(start)) {
        result = new OuterFaceCirculator(start);
    } else {
        result = selectOnOuterFace(predicate, start.getNextNode(dir), stop, dir);
    }
    return result;
}

