static void register(Object value) {
    // a registry of the registered objects
    // to prevent infinite loops when iterating over collections
    static List<Object> registeredObjects = new ArrayList<>();
    // a queue of objects to be registered
    // to prevent the risk of infinite loops
    static List<Object> registerQueue = new ArrayList<>();

    // check if the object is already registered
    if (registeredObjects.contains(value)) {
        // if the object is registered, return
        return;
    }

    // check if the object is currently being registered
    if (registerQueue.contains(value)) {
        // if the object is being registered, add it to the registry
        registeredObjects.add(value);
        // remove the object from the register queue
        registerQueue.remove(value);
        // return
        return;
    }

    // start the registration process
    registerQueue.add(value);

    // while the register queue is not empty
    while (!registerQueue.isEmpty()) {
        // get the next object to be registered
        Object current = registerQueue.remove(0);

        // check if the object is assignable from another class
        if (current.getClass().getSuperclass() != null) {
           // add the object to the register queue
           registerQueue.add(current.getClass().getSuperclass());
        }

        // check if the object is an array
        if (current.getClass().isArray()) {
            // add the object to the register queue
            registerQueue.add(current.getClass().getComponentType());
        }

        // check if the object is an interface
        if (current.getClass().isInterface()) {
            // add the object to the register queue
            registerQueue.add(current.getClass().getInterfaces());
        }

        // check if the object is a class
        if (current.getClass().isClass()) {
            // add the object to the register queue
            registerQueue.add(current.getClass().getSuperclass());
        }
    }

    // register the object
    registeredObjects.add(value);

    // remove the object from the register queue
    registerQueue.remove(value);
}

