String unescapeId(String input) {
        // Step 1: Validate the input
        if (input == null) {
            throw new NullPointerException("Input cannot be null");
        }

        // Step 2: Non-destructively unescape the identifier
        StringBuilder output = new StringBuilder(input.length());
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c == '\\') {
                if (i < input.length() - 1) {
                    char next = input.charAt(i+1);
                    if (next == '\\') {
                        // Escaped backslash
                        output.append('\\');
                        i++;
                    } else if (next == 'u') {
                        // Escaped unicode character
                        String hex = input.substring(i+2, i+6);
                        output.append((char) Integer.parseInt(hex, 16));
                        i += 5;
                    } else {
                        // Invalid escape sequence
                        throw new IllegalArgumentException("Invalid escape sequence at index " + i);
                    }
                } else {
                    // Trailing backslash
                    throw new IllegalArgumentException("Trailing backslash at end of input");
                }
            } else {
                // Normal character
                output.append(c);
            }
        }

        return output.toString();
    }

