public static String toString(final char ch) {
    if (ch < 0 || ch > 0xFFFF) {
        throw new IllegalArgumentException("The character must be a valid Unicode code point.");
    }
    if (ch < 0x80) {
        return new String(new char[]{ch}, 0, 1);
    } else if (ch < 0x800) {
        return new String(new char[]{(char)(0xC0 | (ch >> 6)), (char)(0x80 | (ch & 0x3F))}, 0, 2);
    } else if (ch < 0x10000) {
        return new String(new char[]{(char)(0xE0 | (ch >> 12)), (char)(0x80 | ((ch >> 6) & 0x3F)), (char)(0x80 | (ch & 0x3F))}, 0, 3);
    } else {
        return new String(new char[]{(char)(0xF0 | (ch >> 18)), (char)(0x80 | ((ch >> 12) & 0x3F)), (char)(0x80 | ((ch >> 6) & 0x3F)), (char)(0x80 | (ch & 0x3F))}, 0, 4);
    }
}

