public int readTag() throws IOException {
    // Attempt to read a field tag, returning zero if we have reached EOF.
    // Protocol message parsers use this to read tags, since a protocol message may
    // legally end wherever a tag occurs, and zero is not a valid tag number.

    // Check if we have reached EOF.
    if (isAtEnd()) {
        return 0;
    }

    // Read the field tag.
    int tag = readRawVarint32();

    // Convert the field tag to a protocol buffer tag.
    tag = WireFormat.getTagFieldNumber(tag);

    // Check if the tag is a valid protocol buffer tag.
    if (tag == 0) {
        throw InvalidProtocolBufferException.invalidTag();
    }

    return tag;
}

