public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return new ArrayList<>();
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            long startTime = 0L;
            long endTime = 0L;
            String threadName = "";
            boolean isMainThread = false;

            // parse the line to extract the thread information
            String[] tokens = line.split(",");
            if (tokens.length >= 11) {
                startTime = Long.parseLong(tokens[0]);
                endTime = Long.parseLong(tokens[1]);
                threadName = tokens[2];
                isMainThread = Boolean.parseBoolean(tokens[3]);
            }

            // check if the thread snapshot falls within the time range
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (startTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }

            // create a new thread snapshot
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, startTime, endTime, isMainThread);
            threadSnapshots.add(threadSnapshot);
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    if (timeRanges.isEmpty()) {
        throw new IllegalArgumentException("No time ranges provided.");
    }
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (!timeRange.isValid()) {
            throw new IllegalArgumentException("Invalid time range.");
        }
        if (timeRange.getStartTime() > timeRange.getEndTime()) {
            throw new IllegalArgumentException("Start time is after end time.");
        }
        long startMillis = timeRange.getStartTime().getTime();
        long endMillis = timeRange.getEndTime().getTime();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(",");
                if (parts.length != 5) {
                    throw new IOException("Invalid input file format.");
                }
                long timestamp = Long.parseLong(parts[0]);
                if (timestamp < startMillis || timestamp > endMillis) {
                    continue;
                }
                int threadId = Integer.parseInt(parts[1]);
                int state = Integer.parseInt(parts[2]);
                String stackTrace = parts[3];
                long opID = Long.parseLong(parts[4]);
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadId, state, stackTrace, opID);
                threadSnapshots.add(snapshot);
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    // Read the thread dumps from the file
    List<String> threadDumps = Files.readAllLines(file.toPath());
    // Iterate over the thread dumps and extract the information for each snapshot
    for (String threadDump : threadDumps) {
        long timestamp = 0;
        String threadName = "";
        List<StackTraceElement> stackTrace = new ArrayList<>();
        // Extract the timestamp and thread name
        int firstWhitespace = threadDump.indexOf(' ');
        int secondWhitespace = threadDump.indexOf(' ', firstWhitespace + 1);
        timestamp = Long.parseLong(threadDump.substring(0, firstWhitespace));
        threadName = threadDump.substring(firstWhitespace + 1, secondWhitespace);
        // Extract the stack trace
        String stackTraceString = threadDump.substring(secondWhitespace + 1);
        String[] stackTraceElements = stackTraceString.split(";");
        for (String stackTraceElement : stackTraceElements) {
            String[] parts = stackTraceElement.split("\\.");
            String className = parts[0];
            String methodName = parts[1];
            int lineNumber = Integer.parseInt(parts[2]);
            stackTrace.add(new StackTraceElement(className, methodName, lineNumber));
        }
        // Create a new ThreadSnapshot object with the extracted information
        ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadName, stackTrace);
        threadSnapshots.add(threadSnapshot);
    }
    return threadSnapshots;
}

