            if (range.contains(timestamp)) {
                timeRange = range;
                break;
            }
        }
        if (timeRange != null) {
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadName, state, cpuTime);
            threadSnapshots.add(threadSnapshot);
        }
    }
    reader.close();
    return threadSnapshots;
